class Solution:
    def isValidSudoku(self, board):
        def ok(cells):
            vals = [c for c in cells if c != '.']
            return len(vals) == len(set(vals))
        for i in range(9):
            if not ok(board[i]) or not ok([board[r][i] for r in range(9)]): return False
        for br in range(0, 9, 3):
            for bc in range(0, 9, 3):
                if not ok([board[r][c] for r in range(br, br + 3) for c in range(bc, bc + 3)]): return False
        return True

class Solution:
    def isValidSudoku(self, board):
        rows = [0] * 9; cols = [0] * 9; boxes = [0] * 9
        for r in range(9):
            for c in range(9):
                v = board[r][c]
                if v == '.': continue
                bit = 1 << int(v); b = r // 3 * 3 + c // 3
                if rows[r] & bit or cols[c] & bit or boxes[b] & bit: return False
                rows[r] |= bit; cols[c] |= bit; boxes[b] |= bit
        return True

